const rows = $input.all().map(function (i) { return i.json; });
const f = $('Budget Review Form').first().json;
let total = 0;
const byMerchant = {};
for (const r of rows) {
  const raw = r.Amount || r.amount || r.Debit || r.debit || 0;
  const amt = Math.abs(Number(String(raw).replace(/[^0-9.-]/g, '')) || 0);
  if (!amt) continue;
  total += amt;
  const desc = String(r.Description || r.description || r.Memo || r.Details || 'Other');
  const key = desc.toLowerCase().replace(/[0-9]/g, '').replace(/\s+/g, ' ').trim().slice(0, 25) || 'other';
  byMerchant[key] = (byMerchant[key] || 0) + amt;
}
const top = Object.keys(byMerchant).map(function (k) { return { merchant: k, amount: Math.round(byMerchant[k]) }; }).sort(function (a, b) { return b.amount - a.amount; }).slice(0, 15);
return [{ json: {
  email: f['Your email'] || '',
  budget: Number(f['Monthly budget']) || 0,
  transactionCount: rows.length,
  totalSpend: Math.round(total),
  topSpendingText: top.map(function (t) { return t.merchant + ': ' + t.amount; }).join('\n')
} }];

