parameters.jsCode:
const src = $json.output || $json;
const s = $('Summarize Spending').item.json;
const bullets = function (x) { return Array.isArray(x) ? x.map(function (i) { return '- ' + i; }).join('\n') : (x || ''); };
const join = function (x) { return Array.isArray(x) ? x.join('; ') : (x || ''); };
return {
  email: s.email,
  budget: s.budget,
  totalSpend: s.totalSpend,
  transactionCount: s.transactionCount,
  difference: Math.round(s.totalSpend - s.budget),
  status: String(src.status || 'on_track').toLowerCase(),
  overspendAreas: join(src.overspend_areas),
  overspendList: bullets(src.overspend_areas),
  savingsList: bullets(src.savings_opportunities),
  summary: src.summary || '',
  monthlyPlan: src.monthly_plan || '',
  topSpendingText: s.topSpendingText
};
